cd /tmp && cat > fuzz.pl <<'EOF'
#!/usr/bin/perl
use strict; use warnings;
my $B='/workspace/dataset/test20_executable';
my @sfx=qw(s es ses ies ves ice ouse en um a i us is ex ix ax sis xes ch sh z zz o y f fe man men child ox);
my @pool=('a'..'z','A'..'Z','0'..'9',' ','.','-','_','!','1');
srand(1234);
my ($n,$bad,$eq,$dump)=(0,0,0,0);
my @words;
# structured: real-ish words + suffix perturbations
my @stems=qw(dog cat box quiz wife leaf city boy hero potato radius cactus analysis matrix child ox mouse sheep news series jean police datum medium axis alias bus status virus lens class glass move hive tomato buffalo echo halo piano photo memo);
for my $s (@stems){ push @words,$s; for my $x (@sfx){ push @words,$s.$x; push @words,uc($s).$x; push @words,ucfirst($s).$x; } }
# random
for (1..1500){ my $l=1+int(rand(9)); my $w=''; $w.=$pool[int(rand(@pool))] for 1..$l; push @words,$w; }
# random with trailing forced chars
for (1..600){ my $l=1+int(rand(6)); my $w=''; $w.=$pool[int(rand(@pool))] for 1..$l; $w.=$sfx[int(rand(@sfx))]; push @words,$w; }
# high bytes
for (1..300){ my $l=1+int(rand(5)); my $w=''; $w.=chr(0x80+int(rand(0x80))) for 1..$l; push @words,$w; push @words,'dog'.$w; push @words,$w.'s'; }
my %seen;
for my $w (@words){
  next if $seen{$w}++;
  next if $w eq '' || substr($w,-1) eq ':';
  my @L = split /\n/, `'$B' \Q$w\E 2>/dev/null`, -1;
  pop @L if @L && $L[-1] eq '';
  next unless @L==20;
  $n++;
  my ($sg,$p,$s)=($L[1],$L[18],$L[19]);
  my $ep = ($sg eq $w)?0:1; my $es=1-$ep;
  if($p ne $ep || $s ne $es){ $bad++; print "MISMATCH <<$w>> sing=<<$sg>> P=$p exp=$ep S=$s exp=$es\n" if $dump++<25; }
  if($p eq $s){ $eq++; print "EQUALFLAGS <<$w>> P=$p S=$s sing=<<$sg>>\n" if $eq<25; }
}
print "checked=$n mismatches=$bad equalflags=$eq\n";
EOF
perl fuzz.pl 2>&1 | tail -35

