cd /tmp && cat > bf.pl <<'EOF'
#!/usr/bin/perl
use strict; use warnings;
my $B='/workspace/dataset/test20_executable';
my @a=('a'..'z');
my ($n,$bad)=(0,0);
sub go{ my $w=shift;
  my @L=split /\n/, `$B \Q$w\E 2>/dev/null`,-1; pop @L if @L && $L[-1] eq '';
  return unless @L==20; $n++;
  my ($sg,$p,$s)=($L[1],$L[18],$L[19]);
  my $ep=($sg eq $w)?0:1;
  printf "PREDFAIL <<%s>> sing=<<%s>> P=%s S=%s\n",$w,$sg,$p,$s if $p ne $ep || $s ne (1-$ep);
  print "EQFLAGS <<$w>> P=$p S=$s\n" if $p eq $s;
  my $naive=(substr($w,-1) eq 's')?1:0;
  if($p ne $naive){ $bad++; printf "DEV %-4s naive=%d P=%s sing=<<%s>>\n",$w,$naive,$p,$sg; }
}
for my $x (@a){ go($x) }
for my $x (@a){ for my $y (@a){ go($x.$y) } }
for my $x (@a){ for my $y (@a){ for my $z (@a){ go($x.$y.$z) } } }
print "checked=$n devcount=$bad\n";
EOF
perl bf.pl 2>&1 | tail -60

